// TA-CNT-006 -- ported chord-progression templates.
//
// Source: ldrolez/free-midi-chords, chords.py (prog_maj, prog_min lists).
// https://github.com/ldrolez/free-midi-chords -- MIT licence.
// Ported 2026-09-04: Roman-numeral degree/quality token sequences and their
// mood tags are copied verbatim as text data. No MIDI files, audio, or note
// data from that repository are used -- the actual chord voicings/pitches
// are generated by this codebase's own interval-formula engine in
// chordCatalogue.ts. See content/licences.json ("free-midi-chords-progressions").
//
// The modal set (chromatic/borrowed-degree progressions such as bIII, #IV) was
// added later, read from the file names of the v0.20260314 release's
// "4 Progression/Modal" folder (82 progressions; chords.py lists only 22 of them).

export interface ProgressionTemplate {
  readonly tokens: readonly string[];
  readonly moods: readonly string[];
}

